import ast
from app.services import users


def _validate_and_evaluate(expr: str, user: dict) -> bool:
    try:
        node = ast.parse(expr, mode='eval').body
    except SyntaxError:
        return False

    def check_node(n):
        if isinstance(n, (ast.BoolOp, ast.BinOp, ast.UnaryOp, ast.Compare, ast.Constant, ast.Name,
                            ast.And, ast.Or, ast.Not, ast.Eq, ast.NotEq, ast.Lt, ast.LtE, ast.Gt, ast.GtE,
                            ast.Load)):
            pass
        else:
            return False

        if isinstance(n, ast.Name):
            if n.id not in ['id', 'name', 'email']:
                return False

        for _, value in ast.iter_fields(n):
            if isinstance(value, list):
                for item in value:
                    if isinstance(item, ast.AST) and not check_node(item):
                        return False
            elif isinstance(value, ast.AST):
                if not check_node(value):
                    return False
        return True

    if not check_node(node):
        raise ValueError("invalid filter")

    def eval_node(n, u):
        if isinstance(n, ast.Constant):
            return n.value
        elif isinstance(n, ast.Name):
            return u.get(n.id)
        elif isinstance(n, ast.BoolOp):
            values = [eval_node(v, u) for v in n.values]
            if isinstance(n.op, ast.And):
                return all(values)
            if isinstance(n.op, ast.Or):
                return any(values)
        elif isinstance(n, ast.UnaryOp):
            val = eval_node(n.operand, u)
            if isinstance(n.op, ast.Not):
                return not val
        elif isinstance(n, ast.Compare):
            left = eval_node(n.left, u)
            for op, comparator in zip(n.ops, n.comparators):
                right = eval_node(comparator, u)
                if isinstance(op, ast.Eq):
                    if not (left == right): return False
                elif isinstance(op, ast.NotEq):
                    if not (left != right): return False
                elif isinstance(op, ast.Lt):
                    if not (left < right): return False
                elif isinstance(op, ast.LtE):
                    if not (left <= right): return False
                elif isinstance(op, ast.Gt):
                    if not (left > right): return False
                elif isinstance(op, ast.GtE):
                    if not (left >= right): return False
                else:
                    return False
                left = right
            return True
        return False

    return eval_node(node, user)


def handle_filter_users(params: dict) -> tuple[int, dict]:
    expr = params.get("where")
    if not isinstance(expr, str):
        return 400, {"error": "invalid filter"}

    try:
        all_users = users.get_all_users()
        filtered_users = []
        for u in all_users:
            if _validate_and_evaluate(expr, u):
                filtered_users.append(u)
        filtered_users.sort(key=lambda x: x["id"])
        return 200, {"users": filtered_users}
    except Exception:
        return 400, {"error": "invalid filter"}

